DROP TABLE IF EXISTS "card_forms" CASCADE;
DROP TABLE IF EXISTS "card_stats" CASCADE;
DROP TABLE IF EXISTS "cards" CASCADE;
DROP TABLE IF EXISTS "users" CASCADE;

-- ============================================================================
-- ШПАРГАЛКА ПО ENUM-ЗНАЧЕНИЯМ:
-- rarity:        1=Common, 2=Rare, 3=Epic, 4=Legendary, 5=Champion
-- type:          1=Troop, 2=Building, 3=Spell
-- targets:       1=Ground, 2=Air, 3=AirAndGround, 4=Buildings
-- rangetype:     1=Melee, 2=Ranged, 3=Mixed, 4=None
-- movementspeed: 1=Immobile, 2=Slow, 3=Medium, 4=Fast, 5=VeryFast
-- formtype:      1=Evolution, 2=Hero
-- ============================================================================

-- 1. Таблица cards
CREATE TABLE "cards"
(
    "id"          SERIAL PRIMARY KEY,
    "slug"        VARCHAR(64)  NOT NULL UNIQUE,
    "name"        VARCHAR(100) NOT NULL,
    "rarity"      INT          NOT NULL CHECK ("rarity" BETWEEN 1 AND 5),
    "type"        INT          NOT NULL CHECK ("type" BETWEEN 1 AND 3),
    "elixircost"  INT          NOT NULL CHECK ("elixircost" BETWEEN 1 AND 10),
    "releaseyear" INT          NOT NULL,
    "iconurl"     VARCHAR(255) NOT NULL,
    "description" TEXT         NOT NULL
);

-- 2. Таблица card_stats (1:1 с cards)
CREATE TABLE "card_stats"
(
    "id"                 SERIAL PRIMARY KEY,
    "cardid"             INT         NOT NULL UNIQUE REFERENCES "cards" ("id") ON DELETE CASCADE,
    "targets"            INT         NOT NULL CHECK ("targets" BETWEEN 1 AND 4),
    "rangetype"          INT         NOT NULL CHECK ("rangetype" BETWEEN 1 AND 4),
    "hitspeed"           VARCHAR(20) NOT NULL,
    "movementspeed"      INT         NOT NULL CHECK ("movementspeed" BETWEEN 1 AND 5),
    "customstrategyhtml" TEXT        NOT NULL DEFAULT ''
);

-- 3. Таблица card_forms (1:N с cards)
CREATE TABLE "card_forms"
(
    "id"                 SERIAL PRIMARY KEY,
    "cardid"             INT          NOT NULL REFERENCES "cards" ("id") ON DELETE CASCADE,
    "formtype"           INT          NOT NULL CHECK ("formtype" IN (1, 2)),
    "title"              VARCHAR(100) NOT NULL,
    "cyclesorcost"       INT          NOT NULL,
    "abilitydescription" VARCHAR(300) NOT NULL,
    "formiconurl"        VARCHAR(255) NOT NULL
);

-- 4. Таблица users
CREATE TABLE "users"
(
    "id"           SERIAL PRIMARY KEY,
    "username"     VARCHAR(50)  NOT NULL UNIQUE,
    "email"        VARCHAR(100) NOT NULL UNIQUE,
    "passwordhash" VARCHAR(255) NOT NULL,
    "role"         VARCHAR(20)  NOT NULL DEFAULT 'User'
);

