INSERT INTO "card_stats" ("cardid", "targets", "rangetype", "hitspeed", "movementspeed", "customstrategyhtml")
SELECT c."id", v.targets, v.rangetype, v.hitspeed, v.movementspeed, v.strategy
FROM (VALUES
          ('inferno-tower', 3, 2, '0.4s', 1, '<p>Ставьте <strong>Адскую башню</strong> в центре своей половины, чтобы оба башенных орудия помогали сжигать вражеского танка.</p>'),
          ('lava-hound', 4, 2, '1.3s', 2, '<p>Выпускайте <strong>Адскую гончую</strong> из-за башни короля, чтобы накопить эликсир на связку <strong>LavaLoon</strong> или поддержку воздухом.</p>'),
